/// <summary>
/// CB166_SalesOrderSubstitutes
/// Post sales order creation processing multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METSalesOrderFinalizationAutomateTaskService extends METSysOperationTaskService
{    
    guid                topPickingProcessId;
    MetShipmentId       shipmentId;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSalesOrderShipmentConfirmationContract</c>.
/// </param>
public void process(METSalesOrderFinalizationAutomateContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{        
    while (this.getShipmentIdFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (this.shipmentId)
            {
                METOrderShipmentConfirmation       shipmentConfirmation = METOrderShipmentConfirmation::construct(this.shipmentId);
                shipmentConfirmation.run();
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    METSalesOrderFinalizationAutomateContract contract = dataContract as METSalesOrderFinalizationAutomateContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METPostSalesOrderCreationProcessingQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METSalesOrderShipmentConfirmationContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private MetShipmentId getShipmentIdFromTopPickingQueue(guid _processId, boolean _readPast)
{
    METSalesOrderShipmentConfirmationQueue  postQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    postQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock ShipmentId
        from postQueue
        where postQueue.ProcessId == _processId;

        if (postQueue.RecId)
        {
            this.shipmentId = postQueue.ShipmentId;

            postQueue.delete();
        }
        else
        {
            this.shipmentId = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.shipmentId;


}

